syntax = "proto3";
package user;

message GetUserRequest {
  int64 id = 1;            // 字段号 1，不传字段名
}
message User {
  int64 id = 1;
  string name = 2;
  repeated string roles = 3;
}

service UserService {
  rpc GetUser(GetUserRequest) returns (User);           // 一元
  rpc ListUsers(GetUserRequest) returns (stream User);  // 服务端流
}
